package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.JsonGenerationException;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.io.CharacterEscapes;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for JsonGenerator.writeEmbeddedObject.
 */
public class JsonGenerator_writeEmbeddedObject_TriageGen0Test {

    private JsonGenerator jsonGenerator;

    @Before
    public void setUp() {
        // We use a spy because JsonGenerator is an abstract class.
        // We want to test the real implementation of writeEmbeddedObject 
        // while mocking the abstract methods like writeBinary.
        jsonGenerator = Mockito.spy(new JsonGenerator(null, null) {
            @Override public void setCodec(ObjectCodec oc) {}
            @Override public ObjectCodec getCodec() { return null; }
            @Override public Version version() { return null; }
            @Override public JsonGenerator enable(Feature f) { return this; }
            @Override public JsonGenerator disable(Feature f) { return this; }
            @Override public abstract int getFeatureMask();
            @Override public abstract void setFeatureMask(int values);
            @Override public abstract boolean isEnabled(Feature f);
            @Override public abstract void writeStartArray() throws IOException;
            @Override public abstract void writeEndArray() throws IOException;
            @Override public abstract void writeStartObject() throws IOException;
            @Override public abstract void writeEndObject() throws IOException;
            @Override public abstract void writeFieldName(String name) throws IOException;
            @Override public abstract void writeFieldName(com.fasterxml.jackson.core.io.SerializableString name) throws IOException;
            @Override public abstract void writeString(String text) throws IOException;
            @Override public abstract void writeString(char[] text, int offset, int len) throws IOException;
            @Override public abstract void writeString(com.fasterxml.jackson.core.io.SerializableString text) throws IOException;
            @Override public abstract void writeRawUTF8String(byte[] text, int offset, int length) throws IOException;
            @Override public abstract void writeUTF8String(byte[] text, int offset, int length) throws IOException;
            @Override public abstract void writeRaw(String text) throws IOException;
            @Override public abstract void writeRaw(String text, int offset, int len) throws IOException;
            @Override public abstract void writeRaw(char[] text, int offset, int len) throws IOException;
            @Override public abstract void writeRaw(char c) throws IOException;
            @Override public abstract void writeRaw(com.fasterxml.jackson.core.io.SerializableString raw) throws IOException;
            @Override public abstract void writeRawValue(String text) throws IOException;
            @Override public abstract void writeRawValue(String text, int offset, int len) throws IOException;
            @Override public abstract void writeRawValue(char[] text, int offset, int len) throws IOException;
            @Override public abstract void writeRawValue(com.fasterxml.jackson.core.io.SerializableString raw) throws IOException;
            @Override public abstract void writeBinary(Base64Variant bv, byte[] data, int offset, int len) throws IOException;
            @Override public abstract void writeArray(int[] array, int offset, int length) throws IOException;
            @Override public abstract void writeArray(long[] array, int offset, int length) throws IOException;
            @Override public abstract void writeArray(double[] array, int offset, int length) throws IOException;
            @Override public abstract void writeStartArray(int size) throws IOException;
            @Override public abstract void setSchema(com.fasterxml.jackson.core.schema.FormatSchema schema);
            @Override public abstract com.fasterxml.jackson.core.schema.FormatSchema getSchema();
            @Override public abstract void setPrettyPrinter(com.fasterxml.jackson.core.util.PrettyPrinter pp);
            @Override public abstract com.fasterxml.jackson.core.util.PrettyPrinter getPrettyPrinter();
            @Override public abstract void useDefaultPrettyPrinter() throws IOException;
            @Override public abstract void setHighestNonEscapedChar(int charCode);
            @Override public abstract int getHighestEscapedChar();
            @Override public abstract CharacterEscapes getCharacterEscapes();
            @Override public abstract void setCharacterEscapes(CharacterEscapes esc);
            @Override public abstract void setRootValueSeparator(com.fasterxml.jackson.core.io.SerializableString sep);
            @Override public abstract Object getOutputTarget();
            @Override public abstract int getOutputBuffered();
            @Override public abstract Object getCurrentValue();
            @Override public abstract void setCurrentValue(Object v);
            @Override public abstract boolean canUseSchema(com.fasterxml.jackson.core.schema.FormatSchema schema);
            @Override public abstract boolean canWriteObjectId();
            @Override public abstract boolean canWriteTypeId();
            @Override public abstract boolean canWriteBinaryNatively();
            @Override public abstract boolean canOmitFields();
            @Override public abstract boolean canWriteFormattedNumbers();
            @Override public abstract void writeBinary(byte[] data, int offset, int len) throws IOException;
        });
    }

    /**
     * Tests that passing a byte array calls writeBinary.
     */
    @Test
    public void testWriteEmbeddedObject_withByteArray() throws IOException {
        byte[] data = new byte[]{1, 2, 3, 4};

        jsonGenerator.writeEmbeddedObject(data);

        // Verify that writeBinary was called with the correct arguments
        verify(jsonGenerator, times(1)).writeBinary(data, 0, data.length);
    }

    /**
     * Tests that passing an unsupported type (e.g., String) throws a JsonGenerationException.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_withUnsupportedType() throws IOException {
        String unsupported = "I am not a byte array";

        jsonGenerator.writeEmbeddedObject(unsupported);
    }

    /**
     * Tests that passing null throws a JsonGenerationException because 
     * null is not an instance of byte[].
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_withNull() throws IOException {
        jsonGenerator.writeEmbeddedObject(null);
    }
}
